def two_sum_indices(xs: List[int], target: int) -> Tuple[int, int]:
    seen = {}
    for i, x in enumerate(xs):
        if target - x in seen:
            return (seen[target - x], i)
        seen[x] = i
    raise ValueError("No two sum solution found")
