def sort_colors(xs: list[int]) -> list[int]:
    low = mid = 0
    high = len(xs) - 1

    while mid <= high:
        if xs[mid] == 0:
            xs[low], xs[mid] = xs[mid], xs[low]
            low += 1
            mid += 1
        elif xs[mid] == 1:
            mid += 1
        else:
            xs[mid], xs[high] = xs[high], xs[mid]
            high -= 1

    return xs
```

