def merge_intervals(iv: List[tuple[int, int]]) -> List[tuple[int, int]]:
    if not iv:
        return []

    merged = [iv[0]]
    for interval in iv[1:]:
        if interval[0] <= merged[-1][1]:
            # Check if the current interval can be merged with the last merged interval
            if interval[1] > merged[-1][1]:
                merged[-1] = (merged[-1][0], interval[1])
        else:
            # If the current interval does not overlap with the last merged interval, add it to the list
            merged.append(interval)

